export declare function measure<T>(read: () => T, write: (value: T) => void): void;
export declare function batchMeasures(run: () => void): void;
/** Whether a batch is running: reads taken now, before its writes, find layout clean. */
export declare const inBatch: () => boolean;
/** Runs `end` when the running batch has written everything (to drop what was read for it). */
export declare function afterBatch(end: () => void): void;
